package com.homeos.bridge.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import java.util.concurrent.ConcurrentHashMap
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Material Symbols Rounded, weight 400 (Apache-2.0), as raw SVG path data.
 *
 * Baking the path strings in and letting Compose's own [PathParser] turn them into an [ImageVector]
 * keeps Google's icon geometry without shipping a 4 MB variable font or pulling in
 * material-icons-extended. Material Symbols authors on a 960x960 grid with the origin at the
 * bottom-left (viewBox "0 -960 960 960"), so every path is drawn inside a group translated down by
 * 960 to put it back in Compose's top-left space.
 */
private val cache = ConcurrentHashMap<String, ImageVector>()

private fun icon(name: String, pathData: String): ImageVector = cache.getOrPut(name) {
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    )
        .addGroup(name = name, translationY = 960f)
        .addPath(
            pathData = PathParser().parsePathString(pathData).toNodes(),
            fill = SolidColor(Color.Black),
        )
        .clearGroup()
        .build()
}

